import{_ as s,a0 as l,w as p,s as i,I as a,x as e,a1 as r,A as o,ao as m}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"如何使用圖形化工具遠程管理 Linux上的MySQL | LCTT x X-CMD","titleTemplate":false,"description":"如何使用圖形化工具遠程管理 Linux上的MySQL | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用圖形化工具遠程管理 Linux上的MySQL | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用圖形化工具遠程管理 Linux上的MySQL | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150413 How to manage remote MySQL databases on Linux VPS using a GUI tool","title":"如何使用圖形化工具遠程管理 Linux上的MySQL","tag":"201506","desc":""},"relativePath":"201506/20150413 How to manage remote MySQL databases on Linux VPS using a GUI tool.md","filePath":"[post].md"}'),d={name:"201506/20150413 How to manage remote MySQL databases on Linux VPS using a GUI tool.md"};function u(b,t,S,y,c,L){const n=l("Link");return p(),i("div",null,[t[24]||(t[24]=a("h1",{id:"如何使用圖形化工具遠程管理-linux上的mysql",tabindex:"-1"},[e("如何使用圖形化工具遠程管理 Linux上的MySQL "),a("a",{class:"header-anchor",href:"#如何使用圖形化工具遠程管理-linux上的mysql","aria-label":"Permalink to “如何使用圖形化工具遠程管理 Linux上的MySQL”"},"​")],-1)),a("p",null,[t[2]||(t[2]=e("如果你在一個遠程的VPS上運行了MySQL服務器，你會如何管理你的遠程資料庫主機呢？基於web的資料庫管理工具例如",-1)),r(n,{href:"http://ask.xmodulo.com/install-phpmyadmin-centos.html"},{default:o(()=>[...t[0]||(t[0]=[e("phpMyAdmin",-1)])]),_:1}),t[3]||(t[3]=e("或者",-1)),r(n,{href:"http://xmodulo.com/set-web-based-database-management-system-adminer.html"},{default:o(()=>[...t[1]||(t[1]=[e("Adminer",-1)])]),_:1}),t[4]||(t[4]=e("可能會是你第一個想起的。這些基於web的管理工具需要一個正常運行的後端的web服務和PHP引擎。但是，如果你的VPS僅僅用來做資料庫服務(例如，資料庫與其它服務獨立存放的分佈式結構)，為偶爾的資料庫管理提供一整套的LAMP是浪費VPS資源的。更糟的是，LAMP所打開的HTTP端口可能會成為你VPS資源的安全漏洞。",-1))]),t[25]||(t[25]=a("p",null,"作為一種選擇，你可以使用在一台客户機上運行本地的MySQL客户端，當然，如果沒有別的選擇，一個純淨的MySQL命令列客户端將是你的默認選擇。但是命令列客户端的功能是有限的，因為它沒有生產級資料庫管理功能，例如：可視化SQL開發、性能調優、模式驗證等等。你是否在尋找一個成熟的MySQL管理工具，那麼一個MySQL的圖形化管理工具將會更好的滿足你的需求。",-1)),t[26]||(t[26]=a("p",null,"###什麼是MySQL Workbench?",-1)),a("p",null,[t[6]||(t[6]=e("作為一個由Oracle開發的集成的資料庫管理工具，",-1)),r(n,{href:"http://mysqlworkbench.org/"},{default:o(()=>[...t[5]||(t[5]=[e("MySQL Workbench",-1)])]),_:1}),t[7]||(t[7]=e("不僅僅是一個簡單的MySQL客户端。簡而言之，Workbench是一個跨平台的（如：Linux,MacOX,Windows）資料庫設計、開發和管理的圖形化工具。MySQL Workbench 社區版是遵循GPL協議的。作為一個數據庫管理者，你可以使用Workbench去配置MySQL服務、管理MySQL用户、進行資料庫的備份與還原、監視資料庫的健康狀況，所有的都在對用户友好的圖形化環境下處理。",-1))]),t[27]||(t[27]=a("p",null,"在這個手冊裏，讓我們演示下如何在Linux下安裝和使用MySQL Workbench。",-1)),t[28]||(t[28]=a("p",null,"###在Linux上安裝MySQL Workbench",-1)),t[29]||(t[29]=a("p",null,"你可以在任何一個桌面linux機器上運行MySQL Workbench來設置你的資料庫管理環境。雖然一些Linux發行版（例如：Debian/Ubuntu）在他們的軟件源中已經有了MySQL Workbench，但是從官方源中安裝是一個好的方法，因為他們提供了最新的版本。這裏介紹瞭如何設置一個官方的Workbench軟件源和從中安裝它。",-1)),t[30]||(t[30]=a("h4",{id:"基於-debian-的桌面-debia-ubuntu-mint",tabindex:"-1"},[e("基於 Debian 的桌面 (Debia, Ubuntu, Mint): "),a("a",{class:"header-anchor",href:"#基於-debian-的桌面-debia-ubuntu-mint","aria-label":"Permalink to “基於 Debian 的桌面 (Debia, Ubuntu, Mint):”"},"​")],-1)),a("p",null,[t[9]||(t[9]=e("到其",-1)),r(n,{href:"http://dev.mysql.com/downloads/repo/apt/"},{default:o(()=>[...t[8]||(t[8]=[e("官方站點",-1)])]),_:1}),t[10]||(t[10]=e("，選擇一個和你環境匹配的DEB文件，並下載安裝：",-1))]),t[31]||(t[31]=m(`<p>例如，對於 Ubuntu 14.10：</p><pre><code>$ wget http://dev.mysql.com/get/mysql-apt-config_0.3.4-2ubuntu14.10_all.deb
$ sudo dpkg -i mysql-apt-config_0.3.4-2ubuntu14.10_all.deb
</code></pre><p>對於 Debian 7：</p><pre><code>$ wget http://dev.mysql.com/get/mysql-apt-config_0.3.3-1debian7_all.deb
$ sudo dpkg -i mysql-apt-config_0.3.3-1debian7_all.deb
</code></pre><p>當你安裝DEB文件時，你會看到下面的配置菜單，並且選擇配置那個MySQL產品</p><p><img src="https://farm8.staticflickr.com/7702/16928715218_b1fcbcdbf3_c.jpg" alt=""></p><p>選擇“Utilities”。完成配置後，選擇“Apply”去保存配置。然後，更新包索引，並且安裝Workbench。</p><pre><code>$ sudo apt-get update
$ sudo apt-get install mysql-workbench 
</code></pre><h4 id="基於-red-hat-的桌面-centos-fedora-rhel" tabindex="-1">基於 Red Hat 的桌面 (CentOS, Fedora, RHEL): <a class="header-anchor" href="#基於-red-hat-的桌面-centos-fedora-rhel" aria-label="Permalink to “基於 Red Hat 的桌面 (CentOS, Fedora, RHEL):”">​</a></h4><p>去官網下載並安裝適合你Linux環境的RPM源包。</p><p>例如，對於 CentOS 7：</p><pre><code>$ wget http://dev.mysql.com/get/mysql-community-release-el7-5.noarch.rpm
$ sudo yum localinstall mysql-community-release-el7-5.noarch.rpm
</code></pre><p>對於 Fedora 21：</p><pre><code>$ wget http://dev.mysql.com/get/mysql-community-release-fc21-6.noarch.rpm
$ sudo yum localinstall mysql-community-release-fc21-6.noarch.rpm
</code></pre><p>驗證&quot;MySQL Tools Community&quot;源是否被安裝：</p><pre><code>$ yum repolis enabled 
</code></pre><p><img src="https://farm9.staticflickr.com/8826/16494069254_15458ace52_c.jpg" alt=""></p><p>安裝Workbench</p><pre><code>$ sudo yum install mysql-workbench-community 
</code></pre><p>###設置遠程資料庫的安全連接</p><p>接下來是為你運行MySQL服務的VPS設置一個遠程連接。當然，你可以直接通過圖形化的Workbench連接你的遠程MySQL服務器（在資料庫開放了遠程連接後）。然而，這樣做有很大的安全風險，因為有些人很容易竊聽你的資料庫傳輸信息，並且一個公開的MySQL端口（默認為3306）會是另外一個攻擊入口。</p><p>一個比較好的方法是關掉遠程訪問資料庫服務功能，（僅允許在VPS 上的127.0.0.1訪問）。然後在本地客户機和遠程VPS之間設置一個SSH隧道，這樣的話，和MySQL之間的數據能安全地通過它的本地迴環接口上中繼。相比較設置一個SSL加密的連接來説，配置SSH隧道需要很少的操作，因為它僅僅需要SSH服務，並且在大多數的VPS上已經部署了。</p><p>讓我們來看看如何來為一個MySQL Workbench設置一個SSH隧道。</p><p>在這個設置裏，不需要你開放遠程訪問MySQL服務。</p><p>在一個運行了Workbench的本地客户機上，鍵入下面的命令，替換&#39;user&#39;（遠程 VPS 的用户名）和&#39;remote_vps&#39;（遠程 VPS 的地址）為你自己的信息：</p><pre><code>$ ssh user@remote_vps -L 3306:127.0.0.1:3306 -N
</code></pre><p>你會被要求輸入你VPS的SSH密碼，當你成功登陸VPS後，在本地的3306端口和遠程VPS的3306端口之間將會建立一個SSH隧道。這裏你不會在前台看到任何信息顯示。</p><p>或者你可以選擇在後台運行SSH隧道，按CTRL+Z停止當前的命令，然後輸入bg並且ENTER</p><p><img src="https://farm8.staticflickr.com/7714/16928715438_bf0db49b3b_c.jpg" alt=""></p><p>這樣SSH隧道就會在後台運行了。</p><p>###使用MySQL Workbench遠程管理MySQL服務</p><p>在建立好SSH隧道後，你可以通過MySQL Workbench去遠程連接MySQL服務了。</p><p>輸入下面命令啓動Workbench：</p><pre><code>$ mysql-workbench 
</code></pre><p><img src="https://farm9.staticflickr.com/8768/16494069294_0fce571ddb_c.jpg" alt=""></p><p>點擊Workbench頁面上面的“加號”圖標去創建一個新的資料庫連接，接着會出現下面的連接信息。</p><ul><li><strong>Connection Name</strong>: 任意描述 (例如: My remote VPS database)</li><li><strong>Hostname</strong>: 127.0.0.1</li><li><strong>Port</strong>: 3306</li><li><strong>Username</strong>: MySQL 用户名 (例如 root)</li></ul><p><img src="https://farm8.staticflickr.com/7727/16928715288_d9ac3bfc7a_c.jpg" alt=""></p><p>注意：因為隧道設置的是127.0.0.1:3306，所以主機名字段必須是127.0.0.1，而不能是遠程VPS的IP地址或者主機名。</p><p>當你設置好一個新的資料庫連接後，你會在Workbench窗口看到一個新的框，點擊那個框就會實際去連接遠程的MySQL服務了。</p><p><img src="https://farm8.staticflickr.com/7650/17114969532_0252ffcd31_c.jpg" alt=""></p><p>當你登錄到MySQL 服務器後，你可以再左側面板看到各種管理任務。讓我們來看一些常見的管理任務。</p><h4 id="mysql-server-status" tabindex="-1">MySQL Server Status <a class="header-anchor" href="#mysql-server-status" aria-label="Permalink to “MySQL Server Status”">​</a></h4><p>該菜單顯示了展示資料庫服務器的資源使用情況的實時監控面板。（例如：流量、鏈接、讀寫）</p><p><img src="https://farm8.staticflickr.com/7627/16494069414_9d838d4138_c.jpg" alt=""></p><h4 id="client-connections" tabindex="-1">Client Connections <a class="header-anchor" href="#client-connections" aria-label="Permalink to “Client Connections”">​</a></h4><p>客户端連接數是一個極其重要的監控的資源，這個菜單顯示了每個連接的詳細信息。</p><p><img src="https://farm9.staticflickr.com/8747/16909119337_a8d89772dd_c.jpg" alt=""></p><h4 id="用户和權限" tabindex="-1">用户和權限 <a class="header-anchor" href="#用户和權限" aria-label="Permalink to “用户和權限”">​</a></h4><p>這個菜單允許你管理MySQL用户，包括他們的資源限制和權限。</p><p><img src="https://farm9.staticflickr.com/8765/16494069384_760fc17c8f_c.jpg" alt=""></p><h4 id="mysql-server-administration" tabindex="-1">MySQL Server Administration <a class="header-anchor" href="#mysql-server-administration" aria-label="Permalink to “MySQL Server Administration”">​</a></h4><p>你可以啓動或關閉MySQL服務，並且檢查它的服務日誌。</p><p><img src="https://farm8.staticflickr.com/7588/17114969592_54526dfb32_c.jpg" alt=""></p><h4 id="database-schema-management" tabindex="-1">Database Schema Management <a class="header-anchor" href="#database-schema-management" aria-label="Permalink to “Database Schema Management”">​</a></h4><p>可以可視化的查看、更改、檢查資料庫結構，在“Schemas”標題下選擇任何一個數據庫或表，然後右擊</p><p><img src="https://farm8.staticflickr.com/7665/16496363973_fd03a96198_c.jpg" alt=""></p><p><img src="https://farm9.staticflickr.com/8744/16909119497_7c884617b8_c.jpg" alt=""></p><h4 id="database-query" tabindex="-1">Database Query <a class="header-anchor" href="#database-query" aria-label="Permalink to “Database Query”">​</a></h4><p>你可以執行任何的語句（只要你的權限允許），並且檢查其結果。</p><p><img src="https://farm8.staticflickr.com/7716/17114969692_c0f02bb277_c.jpg" alt=""></p><p>此外，性能統計數據和報表僅用於MySQL5.6以上的版本。對於5.5及其以下的版本，性能部分會以灰色顯示。</p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>簡介且直觀的選項卡界面，豐富的特性，開源，使MySQL Workbench成為一個非常好的可視化資料庫設計和管理工具。為其減分的是它的性能。我注意到在一台運行繁忙的服務器上，Workbench有時會變得異常緩慢，儘管它的性能差強人意，我依然認為MySQL Workbench是MySQL資料庫管理員和設計人員必備的工具之一。</p><p>你曾在你的生產環境中用過Workbench嗎？或者你還有別的GUI工具可以推薦？請分享你的經驗吧。</p><hr>`,66)),a("p",null,[t[12]||(t[12]=e("via: ",-1)),r(n,{href:"http://xmodulo.com/remote-mysql-databases-gui-tool.html"},{default:o(()=>[...t[11]||(t[11]=[e("http://xmodulo.com/remote-mysql-databases-gui-tool.html",-1)])]),_:1})]),a("p",null,[t[16]||(t[16]=e("作者：",-1)),r(n,{href:"http://xmodulo.com/author/nanni"},{default:o(()=>[...t[13]||(t[13]=[e("Dan Nanni",-1)])]),_:1}),t[17]||(t[17]=e(" 譯者：",-1)),r(n,{href:"https://github.com/tyzy313481929"},{default:o(()=>[...t[14]||(t[14]=[e("tyzy313481929",-1)])]),_:1}),t[18]||(t[18]=e(" 校對：",-1)),r(n,{href:"https://github.com/wxy"},{default:o(()=>[...t[15]||(t[15]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[21]||(t[21]=e("本文由 ",-1)),r(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[19]||(t[19]=[e("LCTT",-1)])]),_:1}),t[22]||(t[22]=e(" 原創翻譯，",-1)),r(n,{href:"http://linux.cn/"},{default:o(()=>[...t[20]||(t[20]=[e("Linux中國",-1)])]),_:1}),t[23]||(t[23]=e(" 榮譽推出",-1))])])}const M=s(d,[["render",u]]);export{g as __pageData,M as default};
